import ast
import requests
from bs4 import BeautifulSoup

def task_func(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return []

    soup = BeautifulSoup(response.text, 'html.parser')
    scripts = soup.find_all('script')
    results = []

    for script in scripts:
        content = script.string
        if content:
            try:
                data = ast.literal_eval(content.strip())
                if isinstance(data, dict):
                    results.append(data)
            except (ValueError, SyntaxError):
                continue

    return results

import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests

def task_func(myString):
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    match = re.search(url_pattern, myString)

    if not match:
        return "No valid URL found in the provided string."

    url = match.group(0)

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    soup = BeautifulSoup(response.text, 'html.parser')
    title_tag = soup.find('title')

    if not title_tag or not title_tag.string:
        return "No title tag found in the webpage."

    return title_tag.string.strip()

import ipaddress
import requests

def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range provided.")

    active_ips = []
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            response = requests.get(f"http://{ip_str}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(ip_str)
        except requests.RequestException:
            continue

    return active_ips

